cat > /tmp/functors.txt << 'EOF'


class _FloatConvert:
    """Pickleable functor for float conversion."""
    def __call__(self, s, m=None):
        return float(s)


class _DecimalConvert:
    """Pickleable functor for Decimal conversion."""
    def __call__(self, s, m=None):
        from decimal import Decimal
        return Decimal(s)


class _PercentageConvert:
    """Pickleable functor for percentage conversion."""
    def __call__(self, s, m=None):
        return float(s[:-1]) / 100.0

EOF
sed -i '709r /tmp/functors.txt' /home/parse.py && sed -n '705,735p' /home/parse.py
